package com.vandorlabs.client;
import com.vandorlabs.tiles.*;
import net.minecraft.nbt.*;
/** Actual tile constructor/load/save scalar contract, independent of world callbacks. */
public final class ScreenSettingsLegacyChecks {
 public static final String[] KEYS={"VandorDataVersion","selectedScreen","redstoneEnabled","displayMode","framed","animationSpeedIndex","inputPanel","secondaryInputPanel","wallPosition","smallInput","housingTexture","RedstoneChannel","ChannelSignal","RedstoneChannels","RedstoneInverted","ChannelLevel","PrimarySurfaceTexture","SecondarySurfaceTexture","CeilingMounted","CeilingPosition","SurfaceTextureLayout","SurfaceTileSides"};
 public static final String[] FIELDS={"selectedScreen","redstoneEnabled","displayMode","framed","animationSpeedIndex","inputPanel","secondaryInputPanel","wallPosition","smallInput","housingTexture","RedstoneChannel","ChannelSignal","RedstoneChannels","RedstoneInverted","ChannelLevel","PrimarySurfaceTexture","SecondarySurfaceTexture","CeilingMounted","CeilingPosition","SurfaceTextureLayout","SurfaceTileSides"};
 public static void main(String[] args)throws Exception{net.minecraft.init.Bootstrap.register();net.minecraftforge.fml.common.registry.GameRegistry.registerTileEntity(TileEntityAnimatedScreenSelector.class,new net.minecraft.util.ResourceLocation("minecraft:screen_settings_reference"));java.security.MessageDigest hash=java.security.MessageDigest.getInstance("SHA-256");int cases=0;
  TileEntityAnimatedScreenSelector fresh=new TileEntityAnimatedScreenSelector();digest(hash,fresh);cases++;
  for(String field:FIELDS)for(int kind=0;kind<10;kind++){NBTTagCompound input=input(field,kind);TileEntityAnimatedScreenSelector tile=new TileEntityAnimatedScreenSelector();tile.readFromNBT(input);digest(hash,tile);cases++;}
  for(int mode=0;mode<3;mode++)for(int display=0;display<3;display++)for(int gate=0;gate<2;gate++)for(int signal=0;signal<2;signal++){NBTTagCompound input=new NBTTagCompound(),activation=new NBTTagCompound();activation.setInteger("Mode",mode);activation.setIntArray("Textures",new int[]{-1,-1,-1,-1});activation.setIntArray("Playback",new int[]{-1,0,1,2});activation.setIntArray("Speeds",new int[]{-1,0,1,2});input.setTag("DisplayActivation",activation);input.setInteger("displayMode",display);input.setBoolean("redstoneEnabled",gate!=0);input.setBoolean("ChannelSignal",signal!=0);TileEntityAnimatedScreenSelector tile=new TileEntityAnimatedScreenSelector();tile.readFromNBT(input);digest(hash,tile);cases++;}
  StringBuilder out=new StringBuilder();for(byte b:hash.digest())out.append(String.format("%02x",b&255));if(!out.toString().equals("850c93cfa41b50bffb07a64b5af3abefcb617f26304a6a59eb28b1b717827e23"))throw new AssertionError("Screen scalar reference changed "+out);System.out.println("Actual Screen scalar reference PASS cases="+cases+" sha256="+out);}
 public static NBTTagCompound input(String field,int kind){NBTTagCompound root=new NBTTagCompound();switch(kind){case 0:break;case 1:root.setInteger(field,-9);break;case 2:root.setInteger(field,0);break;case 3:root.setInteger(field,1);break;case 4:root.setInteger(field,Integer.MAX_VALUE);break;case 5:root.setBoolean(field,true);break;case 6:root.setString(field,"future_opaque_display");break;case 7:root.setString(field,"console_controls_biology_controls");break;case 8:root.setIntArray(field,new int[]{31,32});break;default:root.setIntArray(field,new int[]{-1});}return root;}
 private static void digest(java.security.MessageDigest hash,TileEntityAnimatedScreenSelector tile)throws Exception{NBTTagCompound save=tile.writeToNBT(new NBTTagCompound());StringBuilder text=new StringBuilder();for(String key:KEYS)text.append(key).append(':').append(save.hasKey(key)?save.getTag(key).toString():"absent").append(';');hash.update(text.toString().getBytes("UTF-8"));}
}
